// ============================================================================
// 規則名稱：AD - normalize and tag offhours（Stage 0）
// 適用平台：Graylog 7.x  Processing Pipeline Rule
// 用途    ：1) 收斂各採集器的 Windows Event ID → 統一欄位 ad_event_id
//           2) 依事件時間戳（轉台北時區）計算非上班時間布林欄位 ad_off_hours
// 分類    ：Event ID → ad_alert_category 由 Stage 1 的 AD-cat-* 規則承擔；
//           告警端只需過濾 ad_off_hours:true AND ad_alert_category:"<類別>"。
// 範圍    ：僅針對 AD 網域控制站(DC)安全性記錄；請將管線連接到承載 DC 記錄的串流。
// 上班時間：預設週一至週五 09:00–18:00（Asia/Taipei, UTC+8，台灣無日光節約）；可於下方 then 區塊的
//           biz_start / biz_end 兩行以「分鐘」自訂到「幾點幾分」（如 09:30–17:30）。
//           非上班時間 = 週六、週日全天 ＋ 平日上班時段以外。
// ============================================================================
rule "AD - normalize and tag offhours"
when
    // 本環境採集器：NXLog（im_msvistalog）→ GELF，欄位為裸名，已依實機事件確認。
    // 僅處理帶有 Windows Event ID 的訊息，避免對其他記錄做無謂運算與欄位污染。
    // 若日後改用 Winlogbeat，請改 has_field 與下方欄位名（EventID→winlogbeat_winlog_event_id 等）。
    has_field("EventID")
then
    // ---- 1) 正規化 Event ID → ad_event_id（字串）-----------------------------
    // NXLog EventID 為整數，轉字串供 Stage 1 分類規則（AD-cat-*）以等值比對。
    let eid = to_string($message.EventID, "");
    set_field("ad_event_id", eid);

    // ---- 2) 以事件時間戳(轉台北時區)計算 off-hours --------------------------
    // Graylog 內部 timestamp 為 UTC；to_date 帶 "Asia/Taipei" 轉台北時區，
    // 再取 Joda DateTime 屬性 .hourOfDay / .minuteOfHour / .dayOfWeek（ISO 1=週一…7=週日）。
    let ts     = to_date($message.timestamp, "Asia/Taipei");
    let hour   = to_long(ts.hourOfDay);          // 00–23（台北）
    let minute = to_long(ts.minuteOfHour);       // 00–59（台北）
    let dow    = to_long(ts.dayOfWeek);          // ISO：1=週一 … 7=週日
    let mins   = (hour * 60) + minute;           // 一天中的分鐘數 0–1439（供「幾點幾分」級判斷）

    // ==== 上班時間設定（要改上班時段就改這兩行；單位＝一天中的分鐘數）====
    //   換算：時×60＋分。例：09:00=540、09:30=570、17:30=1050、18:00=1080、08:30=510。
    let biz_start = 540;                          // 上班開始（預設 09:00 = 9*60）
    let biz_end   = 1080;                         // 上班結束（預設 18:00 = 18*60）

    // 非上班 = 週末(dow>=6) 或 平日(dow<=5)落在上班時段之外（mins < 開始 或 mins >= 結束）。
    // ★ 直接用「比較式」組布林，勿寫成「let a=..; let b=..; set_field(x, a OR b)」——Graylog 對
    //   「裸變數 OR 裸變數」會拋 VarRefExpression cannot be cast to LogicalExpression（比較式/函式引用不受影響）。
    let off_hours = (dow >= 6) OR ((dow <= 5) AND (mins < biz_start OR mins >= biz_end));
    set_field("ad_off_hours", off_hours);

    // ---- 佐證/除錯用欄位（建立後請用 Simulator 確認，無誤後可選擇移除）-------
    set_field("ad_event_hour", hour);
    set_field("ad_event_min",  minute);
    set_field("ad_event_dow",  dow);
end

// ── [account_create] 帳戶建立：4720 建立使用者帳號 / 624 舊版
rule "AD-cat-account_create"
when
    to_string($message.ad_event_id) == "4720" OR to_string($message.ad_event_id) == "624"
then
    set_field("ad_alert_category", "account_create");
    set_field("ad_watch", true);
end

