// ── [group_modify] 群組修改：4764 類型 / 4735 本機 / 4737 全域 / 4755 通用（雜訊 SamAccountName:'-' 於告警端排除）
rule "AD-cat-group_modify"
when
    to_string($message.ad_event_id) == "4764" OR to_string($message.ad_event_id) == "4735" OR to_string($message.ad_event_id) == "4737" OR to_string($message.ad_event_id) == "4755"
then
    set_field("ad_alert_category", "group_modify");
    set_field("ad_watch", true);
end

