then
    set_field("ad_alert_category", "domain_conn");
    set_field("ad_watch", true);
end

// ── [replication] AD 複寫異常：1988 複寫失敗 / 2042 超過 Tombstone Lifetime
rule "AD-cat-replication"
when
    to_string($message.ad_event_id) == "1988" OR to_string($message.ad_event_id) == "2042"
then
    set_field("ad_alert_category", "replication");
    set_field("ad_watch", true);
end

// ── [audit_tamper] 反鑑識：1102 安全性記錄被清除 / 4719 系統稽核政策變更（皆 High）
rule "AD-cat-audit_tamper"
when
    to_string($message.ad_event_id) == "1102" OR to_string($message.ad_event_id) == "4719"
then
    set_field("ad_alert_category", "audit_tamper");
    set_field("ad_watch", true);
end

// ── [priv_persist] 提權持久化：4765/4766 SID History 注入 / 4794 設定 DSRM 還原模式密碼（皆 High）
rule "AD-cat-priv_persist"
when
    to_string($message.ad_event_id) == "4765" OR to_string($message.ad_event_id) == "4766" OR to_string($message.ad_event_id) == "4794"
then
    set_field("ad_alert_category", "priv_persist");
    set_field("ad_watch", true);
end

// ── [trust_change] 信任/政策竄改：4706/4716 信任關係 / 4865/4866/4867 信任樹 / 4713 Kerberos 政策（Medium）
rule "AD-cat-trust_change"
when
    to_string($message.ad_event_id) == "4706" OR to_string($message.ad_event_id) == "4716" OR to_string($message.ad_event_id) == "4865" OR to_string($message.ad_event_id) == "4866" OR to_string($message.ad_event_id) == "4867" OR to_string($message.ad_event_id) == "4713"
then
    set_field("ad_alert_category", "trust_change");
    set_field("ad_watch", true);
end

// ── [stealth_priv] 隱蔽提權(KDC 憑證)：39/41 KDC 憑證強對應失敗（KB5014754；ESC1/憑證範本濫用訊號）★守門：須來自 System 的 Kerberos-Key-Distribution-Center provider（41 亦為常見 Kernel-Power 關機事件，須防撞號）
rule "AD-cat-stealth_priv_kdc"
when
    (to_string($message.ad_event_id) == "39" OR to_string($message.ad_event_id) == "41")
        AND (contains(to_string($message.SourceName, ""), "Kerberos-Key-Distribution-Center", true) OR contains(to_string($message.SourceName, ""), "Kdc", true))
then
    set_field("ad_alert_category", "stealth_priv");
    set_field("ad_watch", true);
end

// ── [domain_conn] 網域連線(GPO)：1129/1054 群組原則套用事件 ★守門：須來自 System/GroupPolicy channel（小數字 ID 跨來源易撞號）
rule "AD-cat-domain_conn_gpo"
when
    (to_string($message.ad_event_id) == "1129" OR to_string($message.ad_event_id) == "1054")
        AND (contains(to_string($message.Channel, ""), "System", true) OR contains(to_string($message.Channel, ""), "GroupPolicy", true))
then
    set_field("ad_alert_category", "domain_conn");
    set_field("ad_watch", true);
end
